r=subprocess.run(['docker','exec','-i','cps-novel-postgres-1','psql','-X','-v','ON_ERROR_STOP=1','-U','postgres','-d','cps_novel','-At'],input=SQL,text=True,capture_output=True)
print(r.stdout);print(r.stderr);assert r.returncode==0
x=next(json.loads(l) for l in r.stdout.splitlines() if l.startswith('{'))
assert [{'name':m['name'],'checksum':m['checksum']} for m in x['migrations']]==EXPECTED
assert all(m['finished'] and not m['rolled_back'] for m in x['migrations'])
assert x['canonical_tags']==x['homepage_visible']==123 and x['web_update'] and x['business_tables']==58 and x['search_values']==[False]
assert all(i['status']=='skipped' and i['outbox_status']=='accepted' for i in (x['legacy_items'] or []))
assert (x['outbox_urls_by_status'] or {}).get('pending',0)==(x['outbox_urls_by_status'] or {}).get('processing',0)==0
s=x['sweep_schedule_latest'];assert len(s)==10 and all(i['status']=='enqueued' for i in s)
a=[datetime.datetime.fromisoformat(i['scheduled_for']) for i in s];assert all((b-a).total_seconds()==60 for a,b in zip(a,a[1:]))
print('POST_DB_VALIDATION=PASS migrations=26 tables=58 homepage_visible=123 legacy_skipped='+str(len(x['legacy_items'] or [])))
